/* Continue advances the menu clock, while transient combat timers remain paused. */
static void ice_shift83(Ice83*s,int gap){if(s->charge||s->frozen||s->cooldown||s->fracture){s->hitTick+=gap;s->freezeTick+=gap;}}
static void ice_resume83(void){int gap=g.tick-ex.iceLastTick83-1;if(gap>0){pc_ice_shift83(gap);for(int i=0;i<MAXE;i++)if(g.enemies[i].on)ice_shift83(&g.enemies[i].ice83,gap);for(int i=0;i<32;i++)if(ex.env.hazards[i].on)ice_shift83(&ex.env.hazards[i].ice83,gap);if(ex.giant.active){ice_shift83(&ex.giant.ice83,gap);for(int i=0;i<9;i++)ice_shift83(&ex.giant.parts[i].ice83,gap);}}ex.iceLastTick83=g.tick;}
static void ice_step83(void){if(g.mode!=1)return;for(int i=0;i<MAXE;i++){Obj*o=g.enemies+i;if(!o->on)continue;if(o->ice83.frozen&&ice_mini_phase_pending83(o)){o->ice83.frozen=o->ice83.charge=o->ice83.fracture=0;}ice_tick83(&o->ice83,o->x/Q,o->y/Q,pc_enemy_radius(o));}for(int i=0;i<32;i++){EnvironmentHazard*h=ex.env.hazards+i;if(h->on)ice_tick83(&h->ice83,h->x/Q,h->y/Q,h->r);}Giant*b=&ex.giant;if(b->active){if(b->morph||b->openingTicks||b->growthTicks)b->ice83.frozen=0;ice_tick83(&b->ice83,b->parts[6].x,b->parts[6].y,30);for(int i=0;i<9;i++)ice_tick83(&b->parts[i].ice83,b->parts[i].x,b->parts[i].y,b->parts[i].w/2);}}
